  static const decelerate = Cubic(0, 0, 0, 1);
  static const accelerate = Cubic(0.3, 0, 1, 1);

  /// Reads MediaQuery.disableAnimations: animations → 0 ms, hold-to-confirm stays (time-based safety).
  static AppMotion of(BuildContext context) => AppMotion._(MediaQuery.maybeDisableAnimationsOf(context) ?? false);
  Duration get instant => reduced ? Duration.zero : instantBase;
  Duration get fast => reduced ? Duration.zero : fastBase;
  Duration get base => reduced ? Duration.zero : baseBase;
  Duration get slow => reduced ? Duration.zero : slowBase;
  Duration get holdPractice => holdPracticeBase;
  Duration get holdReal => holdRealBase;
}

