/// Semantic colors outside ColorScheme: PnL (incl. neutral ±0), guard, info, trading mode.
@immutable
class TradeColors extends ThemeExtension<TradeColors> {
  const TradeColors({
    required this.profit,
    required this.profitContainer,
    required this.loss,
    required this.lossContainer,
    required this.neutral,
    required this.warning,
    required this.warningContainer,
    required this.guard,
    required this.guardContainer,
    required this.info,
    required this.infoContainer,
    required this.practice,
    required this.practiceContainer,
    required this.onPractice,
    required this.real,
    required this.realContainer,
    required this.onReal,
  });
  final Color profit;
  final Color profitContainer;
  final Color loss;
  final Color lossContainer;
  final Color neutral;
  final Color warning;
  final Color warningContainer;
  final Color guard;
  final Color guardContainer;
  final Color info;
  final Color infoContainer;
  final Color practice;
  final Color practiceContainer;
  final Color onPractice;
  final Color real;
  final Color realContainer;
  final Color onReal;
  static const dark = TradeColors(
    profit: AppColorsDark.semanticProfit,
    profitContainer: AppColorsDark.semanticProfitContainer,
    loss: AppColorsDark.semanticLoss,
    lossContainer: AppColorsDark.semanticLossContainer,
    neutral: AppColorsDark.semanticNeutralPnl,
    warning: AppColorsDark.semanticWarning,
    warningContainer: AppColorsDark.semanticWarningContainer,
    guard: AppColorsDark.semanticGuard,
    guardContainer: AppColorsDark.semanticGuardContainer,
    info: AppColorsDark.semanticInfo,
    infoContainer: AppColorsDark.semanticInfoContainer,
    practice: AppColorsDark.modePractice,
    practiceContainer: AppColorsDark.modePracticeContainer,
    onPractice: AppColorsDark.modeOnPractice,
    real: AppColorsDark.modeReal,
    realContainer: AppColorsDark.modeRealContainer,
    onReal: AppColorsDark.modeOnReal,
  );
  static const light = TradeColors(
    profit: AppColorsLight.semanticProfit,
    profitContainer: AppColorsLight.semanticProfitContainer,
    loss: AppColorsLight.semanticLoss,
    lossContainer: AppColorsLight.semanticLossContainer,
    neutral: AppColorsLight.semanticNeutralPnl,
    warning: AppColorsLight.semanticWarning,
    warningContainer: AppColorsLight.semanticWarningContainer,
    guard: AppColorsLight.semanticGuard,
    guardContainer: AppColorsLight.semanticGuardContainer,
    info: AppColorsLight.semanticInfo,
    infoContainer: AppColorsLight.semanticInfoContainer,
    practice: AppColorsLight.modePractice,
    practiceContainer: AppColorsLight.modePracticeContainer,
    onPractice: AppColorsLight.modeOnPractice,
    real: AppColorsLight.modeReal,
    realContainer: AppColorsLight.modeRealContainer,
    onReal: AppColorsLight.modeOnReal,
  );

  /// PnL color: > 0 profit, < 0 loss, == 0 neutral. Always pair with ▲/▼/± glyph + sign (color-not-only).
  Color pnl(num value) => value > 0 ? profit : (value < 0 ? loss : neutral);

  @override
  TradeColors copyWith({
    Color? profit,
    Color? profitContainer,
    Color? loss,
    Color? lossContainer,
    Color? neutral,
    Color? warning,
    Color? warningContainer,
    Color? guard,
    Color? guardContainer,
    Color? info,
    Color? infoContainer,
    Color? practice,
    Color? practiceContainer,
    Color? onPractice,
    Color? real,
    Color? realContainer,
    Color? onReal,
  }) {
    return TradeColors(
      profit: profit ?? this.profit,
      profitContainer: profitContainer ?? this.profitContainer,
      loss: loss ?? this.loss,
      lossContainer: lossContainer ?? this.lossContainer,
      neutral: neutral ?? this.neutral,
      warning: warning ?? this.warning,
      warningContainer: warningContainer ?? this.warningContainer,
      guard: guard ?? this.guard,
      guardContainer: guardContainer ?? this.guardContainer,
      info: info ?? this.info,
      infoContainer: infoContainer ?? this.infoContainer,
      practice: practice ?? this.practice,
      practiceContainer: practiceContainer ?? this.practiceContainer,
      onPractice: onPractice ?? this.onPractice,
      real: real ?? this.real,
      realContainer: realContainer ?? this.realContainer,
      onReal: onReal ?? this.onReal,
    );
  }

  @override
  TradeColors lerp(ThemeExtension<TradeColors>? other, double t) {
    if (other is! TradeColors) return this;
    return TradeColors(
      profit: Color.lerp(profit, other.profit, t)!,
      profitContainer: Color.lerp(profitContainer, other.profitContainer, t)!,
      loss: Color.lerp(loss, other.loss, t)!,
      lossContainer: Color.lerp(lossContainer, other.lossContainer, t)!,
      neutral: Color.lerp(neutral, other.neutral, t)!,
      warning: Color.lerp(warning, other.warning, t)!,
      warningContainer: Color.lerp(warningContainer, other.warningContainer, t)!,
      guard: Color.lerp(guard, other.guard, t)!,
      guardContainer: Color.lerp(guardContainer, other.guardContainer, t)!,
      info: Color.lerp(info, other.info, t)!,
      infoContainer: Color.lerp(infoContainer, other.infoContainer, t)!,
      practice: Color.lerp(practice, other.practice, t)!,
      practiceContainer: Color.lerp(practiceContainer, other.practiceContainer, t)!,
      onPractice: Color.lerp(onPractice, other.onPractice, t)!,
      real: Color.lerp(real, other.real, t)!,
      realContainer: Color.lerp(realContainer, other.realContainer, t)!,
      onReal: Color.lerp(onReal, other.onReal, t)!,
    );
  }
}

abstract final class AppText {
  static TextStyle _s(double size, double line, FontWeight w, double ls, Color c) => GoogleFonts.inter(
    fontSize: size,
    height: line / size,
    fontWeight: w,
    letterSpacing: ls,
    color: c,
  ).copyWith(fontFamilyFallback: AppFonts.sansFallback);

  /// All 15 Material 3 slots (mapping documented in README).
  static TextTheme theme(Color c, {bool compact = false}) {
    if (compact) {
      return TextTheme(
        displayLarge: _s(28, 34, FontWeight.w600, 0, c),
        displayMedium: _s(28, 34, FontWeight.w600, 0, c),
        displaySmall: _s(28, 34, FontWeight.w600, 0, c),
        headlineLarge: _s(20, 28, FontWeight.w600, 0, c),
        headlineMedium: _s(20, 28, FontWeight.w600, 0, c),
        headlineSmall: _s(16, 24, FontWeight.w600, 0, c),
        titleLarge: _s(16, 24, FontWeight.w600, 0, c),
        titleMedium: _s(14, 20, FontWeight.w600, 0, c),
        titleSmall: _s(12, 16, FontWeight.w600, 0, c),
        bodyLarge: _s(14, 20, FontWeight.w400, 0, c),
        bodyMedium: _s(13, 18, FontWeight.w400, 0, c),
        bodySmall: _s(11, 14, FontWeight.w400, 0, c),
        labelLarge: _s(12, 16, FontWeight.w500, 0, c),
        labelMedium: _s(11, 14, FontWeight.w500, 0, c),
        labelSmall: _s(10, 14, FontWeight.w600, 0.4, c),
      );
    }
    return TextTheme(
      displayLarge: _s(32, 40, FontWeight.w600, 0, c),
      displayMedium: _s(32, 40, FontWeight.w600, 0, c),
      displaySmall: _s(32, 40, FontWeight.w600, 0, c),
      headlineLarge: _s(24, 32, FontWeight.w600, 0, c),
      headlineMedium: _s(24, 32, FontWeight.w600, 0, c),
      headlineSmall: _s(20, 28, FontWeight.w600, 0, c),
      titleLarge: _s(20, 28, FontWeight.w600, 0, c),
      titleMedium: _s(16, 24, FontWeight.w600, 0, c),
      titleSmall: _s(13, 16, FontWeight.w600, 0, c),
      bodyLarge: _s(16, 24, FontWeight.w400, 0, c),
      bodyMedium: _s(14, 20, FontWeight.w400, 0, c),
      bodySmall: _s(12, 16, FontWeight.w400, 0, c),
      labelLarge: _s(13, 16, FontWeight.w500, 0, c),
      labelMedium: _s(12, 16, FontWeight.w500, 0, c),
      labelSmall: _s(11, 16, FontWeight.w600, 0.4, c),
    );
  }

  /// Monospace tabular numbers for SOL / PnL / % / timers. Use for every number.
  static TextStyle num(double size, {FontWeight weight = FontWeight.w500, Color? color}) => GoogleFonts.jetBrainsMono(
    fontSize: size,
    fontWeight: weight,
    color: color,
    fontFeatures: AppFonts.numericFeatures,
  ).copyWith(fontFamilyFallback: AppFonts.monoFallback);
}

